using System;
using System.IO;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Text.Json;
using System.Text.Json.Nodes;
using Mantle.Core.Look.Levitate;
using Xunit;

namespace Mantle.Core.Tests.Look;

/// <summary>
/// lane r16-separation: look-sync v2.3 "separation" (CONTRACT "2026-11-26: v2.3: separation", proto/designs
/// apps-r3/SEPARATION.md 7bfde5f, FROZEN; look-sync b96576b). separation-v23.json next to this file is look-sync's
/// test/fixtures/separation-v23.json at b96576b, byte for byte (git blob 5ee6017f; generated by look-sync's
/// test/fixtures/separation-v23.gen.js, never hand-edited): the 70 shared vectors every port must pass, alpha and sep
/// exactly, S within 1e-6. The other facts are look-sync's test/separation-v23.test.js at b96576b, ported.
/// </summary>
public class SeparationV23Tests
{
    static string Fixture([CallerFilePath] string here = "") => Path.Combine(Path.GetDirectoryName(here)!, "separation-v23.json");

    static int[] Ints(string h) => new[] { 1, 3, 5 }.Select(i => Convert.ToInt32(h.Substring(i, 2), 16)).ToArray();
    static double[][] Uni(string h) => Enumerable.Range(0, 40).Select(_ => Ints(h).Select(v => (double)v).ToArray()).ToArray();
    static string Hex(double[] c) => "#" + string.Concat(c.Select(v => ((int)Math.Floor(v + 0.5)).ToString("X2")));

    /// The finished island over a picture of one colour (look-sync's test helper): the film, then the layer.
    static string Finished(string h, SeparationResult r, string theme)
    {
        var f = Legibility.FilmRgb(theme);
        double[] One(double[] c, double a, (byte R, byte G, byte B) k) => new[] { c[0] * (1 - a) + k.R * a, c[1] * (1 - a) + k.G * a, c[2] * (1 - a) + k.B * a };
        return Hex(One(One(Ints(h).Select(v => (double)v).ToArray(), r.Alpha, f), r.Sep, r.SepRgb));
    }

    [Fact]
    public void Every_shared_separation_vector_passes_all_70()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Fixture()));
        var root = doc.RootElement;
        Assert.Equal("1", root.GetProperty("rev").GetString());   // the generator writes rev as a string
        var sep = root.GetProperty("separate");
        Assert.Equal(Separate.Target, sep.GetProperty("target").GetDouble());
        Assert.Equal(Separate.SplitDark, sep.GetProperty("splitDark").GetDouble());
        Assert.Equal(Separate.SplitLight, sep.GetProperty("splitLight").GetDouble());
        Assert.Equal(Separate.Step, sep.GetProperty("step").GetDouble());
        Assert.Equal(Separate.Max, sep.GetProperty("max").GetDouble());
        var vectors = root.GetProperty("vectors").EnumerateArray().ToArray();
        Assert.Equal(70, vectors.Length);
        int passed = 0;
        foreach (var v in vectors) {
            string theme = v.GetProperty("theme").GetString()!;
            string at = theme + ": " + v.GetProperty("name").GetString();
            double[][] samples = v.GetProperty("samples").EnumerateArray().Select(s => s.EnumerateArray().Select(c => c.GetDouble()).ToArray()).ToArray();
            var r = Legibility.Separation(samples, v.GetProperty("dim").GetDouble(), theme);
            double wantAlpha = v.GetProperty("alpha").GetDouble(), wantSep = v.GetProperty("sep").GetDouble(), wantS = v.GetProperty("S").GetDouble();
            Assert.True(r.Alpha == wantAlpha, at + " alpha: want " + wantAlpha + ", got " + r.Alpha);
            Assert.True(r.Sep == wantSep, at + " sep: want " + wantSep + ", got " + r.Sep);
            Assert.True(r.S.HasValue && Math.Abs(r.S.Value - wantS) <= 1e-6, at + " S: want " + wantS + ", got " + r.S);
            Assert.Equal(Separate.RgbFor(theme), r.SepRgb);
            // LP and LI are not in the vectors: S is their ratio, and both are luminances
            Assert.True(r.LP is >= 0 and <= 1 && r.LI is >= 0 and <= 1, at + " LP / LI");
            Assert.Equal(r.S!.Value, (Math.Max(r.LI!.Value, r.LP!.Value) + 0.05) / (Math.Min(r.LI.Value, r.LP.Value) + 0.05));
            passed++;
        }
        Assert.Equal(70, passed);
    }

    /// SEPARATION.md "Worked examples" (Dim 0: the picture under the island as given): theme, picture, alpha, sep, the
    /// finished colour (null = not given), S rounded to 2 decimals.
    [Theory]
    [InlineData("dark", "#112023", 0.0, 0.10, "#293639", 1.34)]
    [InlineData("dark", "#0A0C0E", 0.0, 0.12, "#27292B", 1.35)]
    [InlineData("dark", "#1E3A3E", 0.48, 0.0, null, 1.32)]       // the lift stops at .08 (1.28), so the fallback darkens (7bfde5f)
    [InlineData("dark", "#2D3C42", 0.40, 0.0, "#1F292D", 1.30)]
    [InlineData("dark", "#5A646E", 0.32, 0.0, null, 1.54)]       // the brightness check alone separates it
    [InlineData("light", "#AAB4BE", 0.40, 0.0, "#C8CFD5", 1.33)]
    [InlineData("light", "#C8D7E1", 0.0, 0.14, "#ADBBC3", 1.34)]
    [InlineData("light", "#FFFFFF", 0.0, 0.14, "#DDDDDD", 1.36)]
    public void Every_worked_example_in_SEPARATION_md(string theme, string h, double alpha, double sep, string? colour, double s)
    {
        var r = Legibility.Separation(Uni(h), 0, theme);
        Assert.Equal(alpha, r.Alpha);
        Assert.Equal(sep, r.Sep);
        Assert.Equal(s, Math.Floor(r.S!.Value * 100 + 0.5) / 100);
        if (colour != null) Assert.Equal(colour, Finished(h, r, theme));
    }

    [Fact]
    public void The_lift_never_pushes_the_guard_sample_past_the_check_target()
    {
        for (int v = 0; v <= 60; v += 3) {
            var c = new double[] { v, v + 4, v + 6 };
            var r = Legibility.Separation(Enumerable.Range(0, 40).Select(_ => c).ToArray(), 0, "dark");
            var g = Enumerable.Range(0, 3).Select(i => (c[i] * (1 - r.Alpha) + new[] { 10.0, 12, 14 }[i] * r.Alpha) * (1 - r.Sep) + 255 * r.Sep).ToArray();
            Assert.True(Legibility.L(new Rgb(g[0], g[1], g[2])) <= LevitateTokens.FilmTarget + 1e-12, "v " + v);
            Assert.True(r.Sep <= Separate.Max && r.Alpha <= LevitateTokens.FilmCap);
        }
    }

    [Fact]
    public void An_island_the_check_already_darkened_keeps_darkening_and_never_gets_the_white_lift()
    {
        var s = Uni("#101418");
        for (int i = 0; i < 6; i++) s[i] = new double[] { 255, 255, 255 };   // bright spots in a dark area
        var r = Legibility.Separation(s, 0, "dark");
        Assert.True(r.Alpha > 0);
        Assert.Equal(0, r.Sep);
    }

    [Fact]
    public void PanelLift_without_separate_is_exactly_v21_and_with_it_adds_sep_and_its_colour()
    {
        var look = JsonNode.Parse("""{"glass":{"dark":{"dim":0.2},"light":{"dim":0.2}}}""");
        foreach (var theme in new[] { "dark", "light" })
            foreach (var h in new[] { "#112023", "#5A646E", "#C8D7E1", "#FFFFFF" }) {
                var s = Uni(h);
                var v21 = Legibility.PanelLift(look, theme, s);
                Assert.Null(v21.Sep);
                Assert.Null(v21.SepRgb);
                Assert.Equal(Legibility.LiftAlpha(s, 0.2, theme), v21.Alpha);
                // the opt-in off is the record v2.1 built, field for field (the default argument is false)
                Assert.Equal(new PanelLiftResult(v21.Alpha, v21.Check, v21.Dim, v21.Film, v21.Text), v21);
                Assert.Equal(v21, Legibility.PanelLift(look, theme, s, separate: false));
                var v23 = Legibility.PanelLift(look, theme, s, separate: true);
                var r = Legibility.Separation(s, 0.2, theme);
                Assert.Equal(r.Alpha, v23.Alpha);
                Assert.Equal(r.Sep, v23.Sep);
                Assert.Equal(r.SepRgb, v23.SepRgb);
                Assert.Equal("on", v23.Check);
            }
        var off = Legibility.PanelLift(JsonNode.Parse("""{"glass":{"dark":{"dim":0.3,"dimAuto":false}}}"""), "dark", Uni("#000000"), separate: true);
        Assert.Equal(0, off.Alpha);
        Assert.Equal(0, off.Sep);
        Assert.Equal("off", off.Check);
        Assert.Equal(Separate.RgbFor("dark"), off.SepRgb);
        var offPlain = Legibility.PanelLift(JsonNode.Parse("""{"glass":{"dark":{"dim":0.3,"dimAuto":false}}}"""), "dark", Uni("#000000"));
        Assert.Equal(new PanelLiftResult(0, "off", 0.3, Legibility.FilmRgb("dark"), "Brightness check off: Dim 0.30 only"), offPlain);
    }

    [Fact]
    public void Bad_input_never_throws_and_means_no_layer()
    {
        var bads = new System.Collections.Generic.List<double[]?[]?> { null, Array.Empty<double[]?>(), new double[]?[] { new double[] { 1 } }, new double[]?[] { null, new[] { double.NaN, 1, 2 } } };
        foreach (var bad in bads) {
            var r = Legibility.Separation(bad, 0.2, "dark");
            Assert.Equal(0, r.Alpha);
            Assert.Equal(0, r.Sep);
            Assert.Null(r.S);
            Assert.Null(r.LP);
            Assert.Null(r.LI);
        }
    }

    [Fact]
    public void The_layer_is_white_in_dark_and_the_shade_in_light()
    {
        Assert.Equal(((byte)255, (byte)255, (byte)255), Separate.RgbFor("dark"));
        Assert.Equal(((byte)255, (byte)255, (byte)255), Separate.RgbFor(null));
        Assert.Equal(((byte)10, (byte)12, (byte)14), Separate.RgbFor("light"));
    }
}
